import random

def scramble_word(word):
    """Scramble the letters of a word."""
    scrambled_letters = ''.join(random.sample(word, len(word)))
    return scrambled_letters

def unscramble_word(scrambled_word):
    """Ask the user to unscramble the letters and return the correct word."""
    correct_word = ''.join(sorted(scrambled_word))
    user_input = input(f"Unscramble the letters: {scrambled_word} ")
    return correct_word == user_input

def main():
    while True:
        word = input("Enter a word to scramble and unscramble: ").lower()
        if len(word) > 0:
            scrambled_word = scramble_word(word)
            if unscramble_word(scrambled_word):
                print(f"Correct! The unscrambled word is: {word}")
